@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix : <http://www.example.org/ontology#> .

<http://www.example.org/ontology/theatre-productions>
    a owl:Ontology ;
    rdfs:label "Theatre Productions Ontology" ;
    rdfs:comment "Ontology for representing theatre festivals, productions, plays, people, and reviews in Italy as described in the theatre productions story." .

### Classes
:TheatreFestival a owl:Class ;
    rdfs:label "Theatre Festival" ;
    rdfs:comment "A festival event where multiple theatre productions are performed." .

:Theatre a owl:Class ;
    rdfs:label "Theatre" ;
    rdfs:comment "A physical location where theatre productions are held." .

:City a owl:Class ;
    rdfs:label "City" ;
    rdfs:comment "A city in which theatres or festivals are located." .

:Country a owl:Class ;
    rdfs:label "Country" ;
    rdfs:comment "A country containing cities." .

:Play a owl:Class ;
    rdfs:label "Play" ;
    rdfs:comment "A dramatic work that can be performed as a theatre production." .

:Production a owl:Class ;
    rdfs:label "Production" ;
    rdfs:comment "A specific staging or setup of a play." .

:Ensemble a owl:Class ;
    rdfs:label "Ensemble" ;
    rdfs:comment "A group of people performing together in a production." .

:Person a owl:Class ;
    rdfs:label "Person" ;
    rdfs:comment "A human individual participating in theatre events." .

:Actor a owl:Class ;
    rdfs:label "Actor" ;
    rdfs:comment "A person who acts in a production." ;
    rdfs:subClassOf :Person .

:Author a owl:Class ;
    rdfs:label "Author" ;
    rdfs:comment "A person who writes plays." ;
    rdfs:subClassOf :Person .

:Role a owl:Class ;
    rdfs:label "Role" ;
    rdfs:comment "A character or function performed by an actor in a production." .

:Review a owl:Class ;
    rdfs:label "Review" ;
    rdfs:comment "A critical evaluation of a production." .

:Newspaper a owl:Class ;
    rdfs:label "Newspaper" ;
    rdfs:comment "A periodical publication that may publish reviews." .

:Act a owl:Class ;
    rdfs:label "Act" ;
    rdfs:comment "A major division within a play." .

:ProductionRoleAssignment a owl:Class ;
    rdfs:label "Production Role Assignment" ;
    rdfs:comment "A reified relation linking an actor, a role, a production, and a time period." .

:EnsembleMembership a owl:Class ;
    rdfs:label "Ensemble Membership" ;
    rdfs:comment "A reified relation linking a person to an ensemble with a time period." .

### Disjointness
:Actor owl:disjointWith :Author .
:Person owl:disjointWith :Theatre , :TheatreFestival , :City , :Country , :Play , :Production , :Ensemble , :Review , :Newspaper , :Act .

### Object Properties
:hasLocation a owl:ObjectProperty ;
    rdfs:label "has location" ;
    rdfs:comment "Links a theatre festival to the city where it is held." ;
    rdfs:domain :TheatreFestival ;
    rdfs:range :City ;
    owl:inverseOf :isLocationOf .

:isLocationOf a owl:ObjectProperty ;
    rdfs:label "is location of" ;
    rdfs:comment "Inverse: links a city to the theatre festival it hosts." ;
    rdfs:domain :City ;
    rdfs:range :TheatreFestival ;
    owl:inverseOf :hasLocation .

:takesPlaceIn a owl:ObjectProperty ;
    rdfs:label "takes place in" ;
    rdfs:comment "Alternative property linking a theatre festival to its city." ;
    rdfs:domain :TheatreFestival ;
    rdfs:range :City ;
    owl:inverseOf :isPlaceOf .

:isPlaceOf a owl:ObjectProperty ;
    rdfs:label "is place of" ;
    rdfs:comment "Inverse: links a city to theatre festivals held there." ;
    rdfs:domain :City ;
    rdfs:range :TheatreFestival ;
    owl:inverseOf :takesPlaceIn .

:featuresPlay a owl:ObjectProperty ;
    rdfs:label "features play" ;
    rdfs:comment "Links a festival to plays that are performed." ;
    rdfs:domain :TheatreFestival ;
    rdfs:range :Play ;
    owl:inverseOf :isFeaturedInFestival .

:isFeaturedInFestival a owl:ObjectProperty ;
    rdfs:label "is featured in festival" ;
    rdfs:comment "Inverse: links a play to the festival it is featured in." ;
    rdfs:domain :Play ;
    rdfs:range :TheatreFestival ;
    owl:inverseOf :featuresPlay .

:locatedInCity a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "located in city" ;
    rdfs:comment "Links a theatre to the city where it is located." ;
    rdfs:domain :Theatre ;
    rdfs:range :City ;
    owl:inverseOf :cityHasTheatre .

:cityHasTheatre a owl:ObjectProperty ;
    rdfs:label "city has theatre" ;
    rdfs:comment "Inverse: links a city to the theatres it contains." ;
    rdfs:domain :City ;
    rdfs:range :Theatre ;
    owl:inverseOf :locatedInCity .

:locatedInCountry a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "located in country" ;
    rdfs:comment "Links a city to its country." ;
    rdfs:domain :City ;
    rdfs:range :Country ;
    owl:inverseOf :countryHasCity .

:countryHasCity a owl:ObjectProperty ;
    rdfs:label "country has city" ;
    rdfs:comment "Inverse: links a country to the cities it contains." ;
    rdfs:domain :Country ;
    rdfs:range :City ;
    owl:inverseOf :locatedInCountry .

:basisOfProduction a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "basis of production" ;
    rdfs:comment "Links a production to the play it is based on." ;
    rdfs:domain :Production ;
    rdfs:range :Play ;
    owl:inverseOf :isBasisForProduction .

:isBasisForProduction a owl:ObjectProperty ;
    rdfs:label "is basis for production" ;
    rdfs:comment "Inverse: links a play to productions based on it." ;
    rdfs:domain :Play ;
    rdfs:range :Production ;
    owl:inverseOf :basisOfProduction .

:hasEnsemble a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "has ensemble" ;
    rdfs:comment "Links a production to its ensemble." ;
    rdfs:domain :Production ;
    rdfs:range :Ensemble ;
    owl:inverseOf :isEnsembleOf .

:isEnsembleOf a owl:ObjectProperty ;
    rdfs:label "is ensemble of" ;
    rdfs:comment "Inverse: links an ensemble to the production it belongs to." ;
    rdfs:domain :Ensemble ;
    rdfs:range :Production ;
    owl:inverseOf :hasEnsemble .

:hasMember a owl:ObjectProperty ;
    rdfs:label "has member" ;
    rdfs:comment "Links an ensemble to its members." ;
    rdfs:domain :Ensemble ;
    rdfs:range :Person ;
    owl:inverseOf :isMemberOf .

:isMemberOf a owl:ObjectProperty ;
    rdfs:label "is member of" ;
    rdfs:comment "Inverse: links a person to the ensemble they belong to." ;
    rdfs:domain :Person ;
    rdfs:range :Ensemble ;
    owl:inverseOf :hasMember .

:hasAuthor a owl:ObjectProperty ;
    rdfs:label "has author" ;
    rdfs:comment "Links a play to its author." ;
    rdfs:domain :Play ;
    rdfs:range :Author ;
    owl:inverseOf :isAuthorOf .

:isAuthorOf a owl:ObjectProperty ;
    rdfs:label "is author of" ;
    rdfs:comment "Inverse: links an author to the plays they wrote." ;
    rdfs:domain :Author ;
    rdfs:range :Play ;
    owl:inverseOf :hasAuthor .

:hasAct a owl:ObjectProperty ;
    rdfs:label "has act" ;
    rdfs:comment "Links a play to its acts." ;
    rdfs:domain :Play ;
    rdfs:range :Act ;
    owl:inverseOf :isActOf .

:isActOf a owl:ObjectProperty ;
    rdfs:label "is act of" ;
    rdfs:comment "Inverse: links an act to the play it belongs to." ;
    rdfs:domain :Act ;
    rdfs:range :Play ;
    owl:inverseOf :hasAct .

:hasReview a owl:ObjectProperty ;
    rdfs:label "has review" ;
    rdfs:comment "Links a production to a review." ;
    rdfs:domain :Production ;
    rdfs:range :Review ;
    owl:inverseOf :isReviewOf .

:isReviewOf a owl:ObjectProperty ;
    rdfs:label "is review of" ;
    rdfs:comment "Inverse: links a review to the production it evaluates." ;
    rdfs:domain :Review ;
    rdfs:range :Production ;
    owl:inverseOf :hasReview .

:givenBy a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "given by" ;
    rdfs:comment "Links a review to the newspaper that published it." ;
    rdfs:domain :Review ;
    rdfs:range :Newspaper ;
    owl:inverseOf :publishesReview .

:publishesReview a owl:ObjectProperty ;
    rdfs:label "publishes review" ;
    rdfs:comment "Inverse: links a newspaper to the reviews it publishes." ;
    rdfs:domain :Newspaper ;
    rdfs:range :Review ;
    owl:inverseOf :givenBy .

:hasProductionRoleAssignment a owl:ObjectProperty ;
    rdfs:label "has production role assignment" ;
    rdfs:comment "Links a production to a production role assignment instance." ;
    rdfs:domain :Production ;
    rdfs:range :ProductionRoleAssignment ;
    owl:inverseOf :isProductionRoleAssignmentOf .

:isProductionRoleAssignmentOf a owl:ObjectProperty ;
    rdfs:label "is production role assignment of" ;
    rdfs:comment "Inverse: links a production role assignment to the production it belongs to." ;
    rdfs:domain :ProductionRoleAssignment ;
    rdfs:range :Production ;
    owl:inverseOf :hasProductionRoleAssignment .

:productionRoleActor a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "production role actor" ;
    rdfs:comment "Links a production role assignment to the actor." ;
    rdfs:domain :ProductionRoleAssignment ;
    rdfs:range :Actor ;
    owl:inverseOf :actorHasProductionRoleAssignment .

:actorHasProductionRoleAssignment a owl:ObjectProperty ;
    rdfs:label "actor has production role assignment" ;
    rdfs:comment "Inverse: links an actor to their production role assignments." ;
    rdfs:domain :Actor ;
    rdfs:range :ProductionRoleAssignment ;
    owl:inverseOf :productionRoleActor .

:productionRoleRole a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "production role role" ;
    rdfs:comment "Links a production role assignment to the role." ;
    rdfs:domain :ProductionRoleAssignment ;
    rdfs:range :Role ;
    owl:inverseOf :roleHasProductionRoleAssignment .

:roleHasProductionRoleAssignment a owl:ObjectProperty ;
    rdfs:label "role has production role assignment" ;
    rdfs:comment "Inverse: links a role to production role assignments." ;
    rdfs:domain :Role ;
    rdfs:range :ProductionRoleAssignment ;
    owl:inverseOf :productionRoleRole .

:hasEnsembleMembership a owl:ObjectProperty ;
    rdfs:label "has ensemble membership" ;
    rdfs:comment "Links an ensemble to an ensemble membership instance." ;
    rdfs:domain :Ensemble ;
    rdfs:range :EnsembleMembership ;
    owl:inverseOf :isEnsembleMembershipOf .

:isEnsembleMembershipOf a owl:ObjectProperty ;
    rdfs:label "is ensemble membership of" ;
    rdfs:comment "Inverse: links an ensemble membership to the ensemble it belongs to." ;
    rdfs:domain :EnsembleMembership ;
    rdfs:range :Ensemble ;
    owl:inverseOf :hasEnsembleMembership .

:ensembleMember a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "ensemble member" ;
    rdfs:comment "Links an ensemble membership to the person." ;
    rdfs:domain :EnsembleMembership ;
    rdfs:range :Person ;
    owl:inverseOf :personHasEnsembleMembership .

:personHasEnsembleMembership a owl:ObjectProperty ;
    rdfs:label "person has ensemble membership" ;
    rdfs:comment "Inverse: links a person to their ensemble memberships." ;
    rdfs:domain :Person ;
    rdfs:range :EnsembleMembership ;
    owl:inverseOf :ensembleMember .

### Data Properties
:heldInYear a owl:DatatypeProperty ;
    rdfs:label "held in year" ;
    rdfs:comment "The year in which a festival is held." ;
    rdfs:domain :TheatreFestival ;
    rdfs:range xsd:gYear .

:writtenDuring a owl:DatatypeProperty ;
    rdfs:label "written during" ;
    rdfs:comment "The period during which a play was written." ;
    rdfs:domain :Play ;
    rdfs:range xsd:string .

:actNumber a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "act number" ;
    rdfs:comment "The number of an act within a play." ;
    rdfs:domain :Act ;
    rdfs:range xsd:integer .

:hasPremier a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has premier" ;
    rdfs:comment "The date and time of the premier of a production." ;
    rdfs:domain :Production ;
    rdfs:range xsd:dateTime .

:starRating a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "star rating" ;
    rdfs:comment "The star rating given in a review." ;
    rdfs:domain :Review ;
    rdfs:range xsd:integer .

:employedSince a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "employed since" ;
    rdfs:comment "The date and time when an actor started working at a theatre." ;
    rdfs:domain :Actor ;
    rdfs:range xsd:dateTime .

:productionRoleTime a owl:DatatypeProperty ;
    rdfs:label "production role time" ;
    rdfs:comment "The time period for which a production role assignment is valid." ;
    rdfs:domain :ProductionRoleAssignment ;
    rdfs:range xsd:string .

:ensembleMembershipTime a owl:DatatypeProperty ;
    rdfs:label "ensemble membership time" ;
    rdfs:comment "The time period for which an ensemble membership is valid." ;
    rdfs:domain :EnsembleMembership ;
    rdfs:range xsd:string .

### Restrictions and Axioms
:Production rdfs:subClassOf [
    a owl:Restriction ;
    owl:onProperty :hasPremier ;
    owl:cardinality 1
] .
